mapper.select:
SELECT r.* FROM rentals r
WHERE r.status = 1 AND r.review_status = 2
AND EXISTS ( SELECT 1 FROM companies c WHERE c.id = r.company_id AND c.status = 1 )
AND EXISTS ( SELECT 1 FROM users u WHERE u.id = r.agent_id AND u.company_id = r.company_id AND u.status = 1 )
AND r.name LIKE CONCAT( '%', REPLACE( REPLACE( REPLACE( TRIM(#{query.keyword}), '=', '==' ), '%', '=%' ), '_', '=_' ), '%' ) ESCAPE '='
AND r.area_code = #{query.areaCode}
AND r.monthly_rent >= #{query.minRent}
AND r.monthly_rent <= #{query.maxRent}
AND r.floor_plan IN
#{floorPlan}
AND r.built_year IS NOT NULL AND r.built_month IS NOT NULL
AND STR_TO_DATE( CONCAT( r.built_year, '-', LPAD(r.built_month, 2, '0'), '-01' ), '%Y-%m-%d' ) <= DATE( DATE_ADD(UTC_TIMESTAMP(), INTERVAL 9 HOUR) )
AND TIMESTAMPDIFF( YEAR, STR_TO_DATE( CONCAT( r.built_year, '-', LPAD(r.built_month, 2, '0'), '-01' ), '%Y-%m-%d' ), DATE( DATE_ADD(UTC_TIMESTAMP(), INTERVAL 9 HOUR) ) ) <= #{query.maxBuildingAge}
AND EXISTS ( SELECT 1 FROM rental_stations rs WHERE rs.rental_id = r.id
AND rs.station_id = #{query.stationId}
AND rs.walking_minutes <= #{query.maxWalkingMinutes}
)
AND EXISTS ( SELECT 1 FROM rental_feature_relations rf INNER JOIN rental_features f ON f.id = rf.feature_id
WHERE rf.rental_id = r.id AND f.code = #{featureCode} AND f.status = 1 )
ORDER BY r.monthly_rent ASC, r.id DESC
ORDER BY r.monthly_rent DESC, r.id DESC
ORDER BY r.area_sqm DESC, r.id DESC
ORDER BY ( SELECT MIN(rs_sort.walking_minutes) FROM rental_stations rs_sort WHERE rs_sort.rental_id = r.id ) IS NULL ASC,
( SELECT MIN(rs_sort.walking_minutes) FROM rental_stations rs_sort WHERE rs_sort.rental_id = r.id ) ASC,
r.id DESC
ORDER BY r.published_at DESC, r.id DESC
